    if sys.stderr is None:
        return
    try:
        sys.stderr.write("pennywise: {}\n".format(message))
        sys.stderr.flush()
    except (OSError, ValueError):
        pass


def _complain_raw(text):
    if sys.stderr is None:
        return
    try:
        sys.stderr.write(text)
        sys.stderr.flush()
    except (OSError, ValueError):
        pass


def _write_stdout(text):
