    The ledger is UTF-8, so output is too; a narrow stdout encoding (``C``
    locale, ``PYTHONIOENCODING=ascii``) must not turn a note like "café" into a
    UnicodeEncodeError. A stream without a byte buffer is already text.
    """
    out = sys.stdout
    buffer = getattr(out, "buffer", None)
    if buffer is None:
        out.write(text)
        out.flush()
        return
    out.flush()
    if os.linesep != "\n":
        text = text.replace("\n", os.linesep)
    buffer.write(text.encode("utf-8"))
    buffer.flush()


