    """Rewrite ``--category -x`` as ``--category=-x`` for list.

    A value starting with a dash is taken as the category unless it is one of the
    command's own options, so ``--category --json`` is still a command-line error.
    """
    if not argv or argv[0] != "list":
        return argv
    sub = _build_parser()._subparsers._group_actions[0].choices[argv[0]]
    known = [opt for opt in sub._option_string_actions]
    longs = [opt for opt in known if opt.startswith("--")]

    def is_option(word):
        name = word.split("=", 1)[0]
        if name in known:
            return True
        return name.startswith("--") and len(name) > 2 and any(o.startswith(name) for o in longs)

    out = []
    i = 0
    while i < len(argv):
        word = argv[i]
        if word == "--":
            out.extend(argv[i:])
            break
        takes_value = len(word) > 2 and word.startswith("--") and "--category".startswith(word)
        if takes_value and i + 1 < len(argv) and argv[i + 1].startswith("-") and not is_option(argv[i + 1]):
            out.append("--category=" + argv[i + 1])
            i += 2
            continue
        out.append(word)
        i += 1
    return out


def main(argv=None):
    """Run the command line; return the exit status."""
    argv = list(sys.argv[1:] if argv is None else argv)
    try:
        args = _literal_add(argv)
        if args is None:
            args = _build_parser().parse_args(_attach_category_values(argv))
    except SystemExit as exc:
        code = exc.code
        return 0 if code is None else code
    try:
        output = args.func(args)
    except _Fail as exc:
        _complain(exc.message)
        return exc.code
    if sys.stdout is None:
        # Standard output is closed (e.g. `>&-`): nowhere to print.
        _complain("cannot write standard output")
        return 2
    try:
        _write_stdout(output)
    except BrokenPipeError:
        # The reader closed the pipe early (e.g. `| head -1`). Point stdout at
        # devnull so the flush at interpreter exit cannot fail again, and end quietly.
        try:
            os.dup2(os.open(os.devnull, os.O_WRONLY), sys.stdout.fileno())
        except (OSError, ValueError):
            pass
    return 0
